// ============================================================
// TRANSFORMATION PROMETHEUS
// Métriques système, conteneurs et processus
// Synchronisées avec l'incident Centreon
// ============================================================

const results = $input.first().json.data?.result || [];

if (results.length === 0) {
  return [{
    json: {
      nombre_metriques: 0,
      prometheus_formate: "Aucune métrique système Prometheus disponible."
    }
  }];
}

// Timestamp d'évaluation retourné par Prometheus
const timestamp = Number(results[0].value?.[0]);

const dateEvaluation = Number.isFinite(timestamp)
  ? new Date(timestamp * 1000).toISOString()
  : "Non disponible";

// Informations générales
let promMetrics = [
  "=== MÉTRIQUES PROMETHEUS ===",
  `Hôte : ${$('Webhook').first().json.body.host}`,
  `Date d'évaluation : ${dateEvaluation}`,
  "Source : Prometheus",
  "",
  "IMPORTANT :",
  "- cpu_percent représente une utilisation CPU moyenne sur 5 minutes.",
  "- top_process_cpu_percent représente une consommation CPU sur 2 minutes.",
  "- Pour les processus, 100 % correspond approximativement à un cœur CPU.",
  "- Les autres métriques sont évaluées à l'heure indiquée ci-dessus.",
  "- Le timestamp d'évaluation ne garantit pas que chaque échantillon brut a été collecté à cet instant précis.",
  "",
  "MESURES :"
].join("\n") + "\n";

// ------------------------------------------------------------
// Transformation des métriques
// ------------------------------------------------------------

for (const item of results) {

  const metricName =
    item.metric?.metric ||
    item.metric?.__name__ ||
    "Métrique inconnue";

  const containerLabel =
    item.metric?.name ||
    item.metric?.container ||
    item.metric?.container_name ||
    item.metric?.id;

  const containerName = containerLabel
    ? ` [Conteneur: ${containerLabel}]`
    : "";

  const processLabel = item.metric?.groupname;

  const processName = processLabel
    ? ` [Processus: ${processLabel}]`
    : "";

  const metricValue = Number(item.value?.[1]);

  if (!Number.isFinite(metricValue)) {
    continue;
  }

  let unit = "";
  let displayValue = metricValue.toFixed(2);

  if (metricName.includes("percent")) {
    unit = "%";

  } else if (metricName.includes("bytes_per_sec")) {
    unit = " octets/s";

  } else if (metricName.includes("ram_mb")) {
    unit = " Mo";

  } else if (metricName === "top_process_ram_bytes") {
    displayValue = (metricValue / 1024 / 1024).toFixed(2);
    unit = " Mo";
  }

  promMetrics +=
    `- ${metricName}${containerName}${processName} : ${displayValue}${unit}\n`;
}

// ------------------------------------------------------------
// Résultat n8n
// ------------------------------------------------------------

return [{
  json: {
    source: "Prometheus",
    timestamp_evaluation: dateEvaluation,
    nombre_metriques: results.length,
    prometheus_formate: promMetrics
  }
}];

const embedding = $json.data[0].embedding;
const data = $('Code Validation').item.json;

return {
  json: {
    points: [{
      id: data.ticket_id,
      vector: embedding,  // tableau direct, plus de { dense: ... }
      payload: {
        content: data.text,
        titre: data.titre,
        serveur: data.serveur,
        solution: data.text,
        date: data.date,
        duree_minutes: data.duree_minutes,
        ticket_id: data.ticket_id
      }
    }]
  }
};

// Gestion tableau ou objet direct
const raw = $input.first().json;
const ticket = Array.isArray(raw) ? raw[0] : raw;

const dureeMinutes = Math.round((ticket.solve_delay_stat || 0) / 60);
const contenu = ticket.content?.replace(/<[^>]*>/g, '').trim() || "";
const updater = ticket.users_id_lastupdater || 0;

if (updater === 0) {
  return [{ json: { eligible: false, raison: "Aucun utilisateur impliqué" } }];
}

if (dureeMinutes < 2) {
  return [{ json: { eligible: false, raison: `Trop rapide: ${dureeMinutes} min` } }];
}

if (contenu.length < 100) {
  return [{ json: { eligible: false, raison: "Contenu trop court" } }];
}

// Extraction du serveur depuis le contenu
const serveurMatch = contenu.match(/Serveur\s*:\s*(\S+)/);
const serveur = serveurMatch ? serveurMatch[1] : $('Webhook').item.json.body.host || "inconnu";

// Texte à vectoriser
const texte = `
Titre: ${ticket.name}
Serveur: ${serveur}
Durée résolution: ${dureeMinutes} minutes
Diagnostic et solution:
${contenu}
`.trim();

return [{
  json: {
    eligible: true,
    text: texte,
    ticket_id: ticket.id,
    titre: ticket.name,
    serveur: serveur,
    duree_minutes: dureeMinutes,
    date: ticket.closedate
  }
}];

